                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if [ "$lang" = "es" ]; then print_msg "$RED" "No tienes suficientes monedas."; else print_msg "$RED" "Not enough money."; fi
